let sparks = [];

function setup() {
  createCanvas(400, 400);
}

function draw() {
  background(0, 26, 51);
  for (let i = sparks.length - 1; i >= 0; i--) {
    let s = sparks[i];
    s.x += s.vx;
    s.y += s.vy;
    s.vy += 0.1;
    s.life -= 2;
    if (s.life <= 0) {
      sparks.splice(i, 1);
      continue;
    }
    noStroke();
    fill(s.r, s.g, s.b, s.life);
    circle(s.x, s.y, 8);
  }
  fill(255, 204, 0);
  rect(150, 350, 100, 30, 15);
  fill(50);
  textAlign(CENTER, CENTER);
  textSize(16);
  text('うちあげ！', 200, 365);
}

function mousePressed() {
  if (mouseX > 150 && mouseX < 250 && mouseY > 350 && mouseY < 380) {
    for (let i = 0; i < 30; i++) {
      let a = (i / 30) * TWO_PI;
      sparks.push({x: 200, y: 200, vx: cos(a) * 3, vy: sin(a) * 3, life: 255, r: random(255), g: random(255), b: random(255)});
    }
  }
}

let balls = [];
let cols = ['#ff4444','#ffaa00','#ffee00','#44dd44','#44ddee','#5577ff','#cc44ff'];

function setup() {
  createCanvas(400, 400);
  for (let i = 0; i < 7; i++) {
    balls.push({x: random(width), y: random(height), vx: random(-3, 3), vy: random(-3, 3), c: cols[i]});
  }
}

function draw() {
  background(17);
  for (let b of balls) {
    b.x += b.vx;
    b.y += b.vy;
    if (b.x < 30 || b.x > width - 30) b.vx *= -1;
    if (b.y < 30 || b.y > height - 30) b.vy *= -1;
    noStroke();
    fill(b.c);
    circle(b.x, b.y, 50);
  }
}

