let holes = [];
let score = 0;
let activeIdx = -1;
let lastSwitch = 0;

function setup() {
  createCanvas(400, 400);
  for (let r = 0; r < 3; r++) {
    for (let c = 0; c < 3; c++) {
      holes.push({x: 80 + c * 120, y: 120 + r * 90, active: false});
    }
  }
  textAlign(CENTER, CENTER);
}

function draw() {
  background(74, 139, 58);
  if (millis() - lastSwitch > 800) {
    lastSwitch = millis();
    holes.forEach(h => h.active = false);
    activeIdx = floor(random(holes.length));
    holes[activeIdx].active = true;
  }
  fill(255);
  textSize(24);
  text('スコア: ' + score, width/2, 40);
  for (let h of holes) {
    fill(45, 90, 34);
    ellipse(h.x, h.y, 80, 50);
    if (h.active) {
      textSize(50);
      text('🐹', h.x, h.y - 10);
    }
  }
}

function mousePressed() {
  for (let h of holes) {
    if (h.active && dist(mouseX, mouseY, h.x, h.y) < 40) {
      score++;
      h.active = false;
    }
  }
}

